package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.*;import java.io.*;import java.util.*;import org.json.*;

/** Explicit preview/confirmation before replacing the supported Leo data. */
public final class BackupActivity extends LeoActivity {
 private File boundary;private boolean busy;private final java.util.Set<String> chosen=new java.util.HashSet<String>(java.util.Arrays.asList(BackupEngine.CATEGORIES));
 protected void onCreate(Bundle b){super.onCreate(b);worker.execute(new Runnable(){public void run(){try{BackupEngine.recover(BackupActivity.this);ui(new Runnable(){public void run(){String path=getIntent().getStringExtra("file");if(path==null)home();else preview(new File(path));}});}catch(Exception e){ui(new Runnable(){public void run(){begin(L.t("Recuperare backup"));root.addView(text(L.t("Copia de recuperare este păstrată local. Reinstalează tastatura Leo și redeschide Backup dacă furnizorul dicționarului lipsește."),17));footer("","",L.t("Înapoi"));}});}}});}
 private void home(){busy=false;list("Backup Leo",Arrays.asList(L.t("Creează backup"),L.t("Restaurează din fișier"),L.t("Copii automate de recuperare"),L.t("Ce include backup-ul"),L.t("Contacte și SMS · selectiv")),0,new Choice(){public void pick(int i){if(i==4)startActivity(new Intent(BackupActivity.this,PeopleBackupActivity.class));else if(i==0)destinations();else if(i==1)roots();else if(i==2){boundary=new File(getFilesDir(),"documents/Backup-rollback");boundary.mkdirs();browse(boundary);}else options(L.t("Date locale incluse"),new String[]{L.t("Teme, fundal și ordinea aplicațiilor"),L.t("Scurtături și favorite"),L.t("Notițe și ciorna notiței"),L.t("Dicționar T9 și opțiuni tastatură"),L.t("Favorite muzică și aplicații Android"),L.t("Calendar local Leo · maximum 500"),L.t("Alarme Leo"),L.t("Preferințe aplicații și limbă"),L.t("Restaurare pe categorii"),L.t("Fără conturi, parole sau SMS"),L.t("Fișier personal, fără criptare")},new Choice(){public void pick(int n){}});}},"",null);}
 private void destinations(){final ArrayList<File> folders=new ArrayList<File>();ArrayList<String> names=new ArrayList<String>();for(Map.Entry<String,File> r:LeoFileProvider.roots(this).entrySet()){folders.add(new File(r.getValue(),r.getKey().equals("leo")?"Backup":"Documents/LeoBackups"));names.add(r.getKey().equals("phone")?L.t("Memorie telefon"):r.getKey().equals("leo")?L.t("Documente Leo"):L.t("Card SD"));}list(L.t("Salvează backup"),names,0,new Choice(){public void pick(final int i){if(busy)return;busy=true;begin(L.t("Creez backup"));root.addView(text(L.t("Se salvează local…"),18));footer("","",L.t("Așteaptă"));worker.execute(new Runnable(){public void run(){try{final File result=BackupEngine.export(BackupActivity.this,folders.get(i));ui(new Runnable(){public void run(){busy=false;begin(L.t("Backup salvat"));root.addView(text(result.getName()+"\n\n"+android.text.format.Formatter.formatFileSize(BackupActivity.this,result.length())+L.t("\n\nÎl găsești în Fișiere Leo; conține date personale."),17),new android.widget.LinearLayout.LayoutParams(-1,0,1));back=new Runnable(){public void run(){home();}};footer("","",L.t("Înapoi"));}});}catch(final Exception e){ui(new Runnable(){public void run(){home();notice(L.t("Backup eșuat: ")+e.getMessage());}});}}});}},"",null);back=new Runnable(){public void run(){home();}};}
 private void roots(){final LinkedHashMap<String,File> roots=LeoFileProvider.roots(this);final ArrayList<File> dirs=new ArrayList<File>(roots.values());ArrayList<String> names=new ArrayList<String>();for(String key:roots.keySet())names.add(key.equals("phone")?L.t("Memorie telefon"):key.equals("leo")?L.t("Documente Leo"):L.t("Card SD"));list(L.t("Caută backup"),names,0,new Choice(){public void pick(int i){boundary=dirs.get(i);browse(boundary);}},"",null);back=new Runnable(){public void run(){home();}};}
 private void browse(final File dir){try{if(!LeoFileProvider.inside(boundary,dir))throw new IOException();File[] all=dir.listFiles();if(all==null)throw new IOException();Arrays.sort(all,new Comparator<File>(){public int compare(File a,File b){return a.isDirectory()!=b.isDirectory()?a.isDirectory()?-1:1:a.getName().compareToIgnoreCase(b.getName());}});final ArrayList<File> files=new ArrayList<File>();ArrayList<String> labels=new ArrayList<String>();for(File f:all)if(files.size()<300&&LeoFileProvider.inside(boundary,f)&&(f.isDirectory()||f.getName().endsWith(".leo-backup.json"))){files.add(f);labels.add((f.isDirectory()?"▸ ":"")+f.getName());}list(L.t("Backup-uri locale"),labels,0,new Choice(){public void pick(int i){File f=files.get(i);if(f.isDirectory())browse(f);else preview(f);}},"",null);back=new Runnable(){public void run(){if(dir.equals(boundary))roots();else browse(dir.getParentFile());}};}catch(IOException e){notice(L.t("Folder inaccesibil"));}}
 private void preview(final File file){if(busy)return;boolean allowed=false;try{for(File root:LeoFileProvider.roots(this).values())if(LeoFileProvider.inside(root,file))allowed=true;}catch(IOException ignored){}if(!allowed||!file.isFile()){home();notice(L.t("Backup în afara stocării permise"));return;}busy=true;begin(L.t("Verific backup-ul"));root.addView(text(L.t("Verific integritatea și formatul…"),18));footer("","",L.t("Așteaptă"));worker.execute(new Runnable(){public void run(){try{final JSONObject data=BackupEngine.read(BackupActivity.this,file);final ArrayList<String> info=new ArrayList<String>();info.add(L.t("Preferințe · ")+data.getJSONObject("preferences").length()+L.t(" grupuri"));info.add(L.t("Notițe · ")+(data.isNull("notes")?0:data.getJSONArray("notes").length()));info.add(L.t("Fundal · ")+(data.isNull("wallpaper")?L.t("Nu"):L.t("Da")));String words=data.getJSONObject("dictionary").getString("words");info.add(L.t("Dicționar · ")+(words.isEmpty()?0:words.split("\n").length)+L.t(" cuvinte"));info.add("Calendar Leo · "+(data.has("calendar")?data.getJSONArray("calendar").length():L.t("absent în această copie")));if(data.getJSONObject("preferences").has("alarms"))info.add(L.t("Alarme Leo")+" · "+new org.json.JSONArray(data.getJSONObject("preferences").getJSONObject("alarms").getJSONObject("items").getString("value")).length());info.add(L.t("Restaurează → alege categoriile"));ui(new Runnable(){public void run(){busy=false;list(L.t("Previzualizare backup"),info,0,new Choice(){public void pick(int i){}},L.t("Restaurează"),new Runnable(){public void run(){categories(data);}});back=new Runnable(){public void run(){home();}};}});}catch(final Exception e){ui(new Runnable(){public void run(){home();notice(L.t("Backup respins: ")+e.getMessage());}});}}});}
 private void categories(final JSONObject data){final String[] names={L.t("Aspect, scurtături și Ceas"),L.t("Favorite și aplicații ascunse"),L.t("Notițe și șabloane SMS"),L.t("Tastatură și dicționar"),L.t("Calendar Leo · înlocuiește evenimentele locale"),L.t("Alarme Leo"),L.t("Preferințe aplicații și limbă")};final ArrayList<String> ids=new ArrayList<String>(),labels=new ArrayList<String>();for(int i=0;i<BackupEngine.CATEGORIES.length;i++){String key=BackupEngine.CATEGORIES[i];if(key.equals("calendar")&&!data.has("calendar"))continue;if(key.equals("alarms")&&!data.optJSONObject("preferences").has("alarms"))continue;ids.add(key);labels.add((chosen.contains(key)?"☑ ":"☐ ")+names[i]);}list(L.t("Alege ce restaurezi"),labels,0,new Choice(){public void pick(int i){String key=ids.get(i);if(!chosen.remove(key))chosen.add(key);categories(data);}},L.t("Aplică"),new Runnable(){public void run(){if(chosen.isEmpty()){notice(L.t("Alege cel puțin o categorie"));return;}options(L.t("Înlocuiești categoriile bifate?"),new String[]{L.t("Păstrează datele"),L.t("Restaurează selecția")},new Choice(){public void pick(int i){if(i==1)restore(data);}});}});back=new Runnable(){public void run(){home();}};}
 private void restore(final JSONObject data){busy=true;begin(L.t("Restaurez Leo"));root.addView(text(L.t("Se creează copia de siguranță și se aplică datele…"),18));footer("","",L.t("Așteaptă"));worker.execute(new Runnable(){public void run(){try{BackupEngine.restore(BackupActivity.this,data,new java.util.HashSet<String>(chosen));ui(new Runnable(){public void run(){notice(L.t("Restaurare terminată; copia anterioară este în Documente Leo"));startActivity(new Intent(BackupActivity.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();}});}catch(final Exception e){ui(new Runnable(){public void run(){home();notice(L.t("Restaurare oprită: ")+e.getMessage());}});}}});}
 public void onBackPressed(){if(busy){notice(L.t("Operație în curs"));return;}super.onBackPressed();}
 public boolean onKeyDown(int key,android.view.KeyEvent e){if(busy&&key==android.view.KeyEvent.KEYCODE_BACK){notice(L.t("Operație în curs"));return true;}return super.onKeyDown(key,e);}
}
